package com.example.takura.privacy;
import static org.assertj.core.api.Assertions.*;import com.example.takura.identity.domain.StaffPrincipal;import com.example.takura.privacy.application.PrivacyOperationsService;import java.sql.Timestamp;import java.time.*;import java.util.*;import org.flywaydb.core.Flyway;import org.junit.jupiter.api.*;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.jdbc.datasource.DriverManagerDataSource;import org.testcontainers.containers.PostgreSQLContainer;import org.testcontainers.junit.jupiter.*;
@Testcontainers(disabledWithoutDocker=true)class PrivacyOperationsPostgresqlTest{@Container static final PostgreSQLContainer<?> DB=new PostgreSQLContainer<>("postgres:17.11-alpine3.24");static JdbcTemplate jdbc;PrivacyOperationsService service;UUID requester,approver,enquiry;Instant now=Instant.parse("2026-10-21T08:00:00Z");@BeforeAll static void migrate(){var ds=new DriverManagerDataSource(DB.getJdbcUrl(),DB.getUsername(),DB.getPassword());Flyway.configure().dataSource(ds).locations("classpath:db/migration").defaultSchema("takura").schemas("takura").load().migrate();jdbc=new JdbcTemplate(ds);}@BeforeEach void setup(){jdbc.execute("TRUNCATE takura.privacy_request,takura.legal_hold,takura.deletion_tombstone,takura.operational_audit,takura.notification_outbox,takura.enquiry,takura.staff_identity CASCADE");requester=identity("requester");approver=identity("approver");enquiry=enquiry("=formula-name");service=new PrivacyOperationsService(jdbc,Clock.fixed(now,ZoneOffset.UTC));}
 @Test void accessExportIsScopedApprovedAndFormulaNeutralised(){var request=service.create(requester(),enquiry,new PrivacyOperationsService.Command("ACCESS","verified-call-reference","Only this enquiry"));var approved=service.approve(approver(),request.id(),0);String csv=service.accessCsv(exporter(),approved.id());assertThat(csv).contains("\"'=formula-name\"").doesNotContain("privacy-secret-token");}
 @Test void holdBlocksDeletionAndApprovedDeletionScrubsAndReplays(){var held=service.create(requester(),enquiry,new PrivacyOperationsService.Command("DELETION","verified-call-reference","Only this enquiry"));var approved=service.approve(approver(),held.id(),0);service.placeHold(holder(),enquiry,"Synthetic dispute hold");assertThat(service.executeDeletion(deleter(),approved.id(),1,"blocked").state()).isEqualTo("BLOCKED_BY_HOLD");UUID other=enquiry("Private Customer");var deletion=service.approve(approver(),service.create(requester(),other,new PrivacyOperationsService.Command("DELETION","verified-call-reference","Only second enquiry")).id(),0);assertThat(service.executeDeletion(deleter(),deletion.id(),1,"approved").state()).isEqualTo("COMPLETED");jdbc.update("UPDATE takura.enquiry SET full_name='Restored private name',marketing_opt_in=true WHERE id=?",other);service.replayTombstones();assertThat(jdbc.queryForObject("SELECT full_name FROM takura.enquiry WHERE id=?",String.class,other)).isEqualTo("Deleted customer");assertThat(jdbc.queryForObject("SELECT marketing_opt_in FROM takura.enquiry WHERE id=?",Boolean.class,other)).isFalse();}
 private UUID identity(String subject){UUID id=UUID.randomUUID();jdbc.update("INSERT INTO takura.staff_identity(id,issuer,subject,display_label,active,provisioned_at,revocation_boundary) VALUES(?,'issuer',?,?,true,?,?)",id,subject,subject,Timestamp.from(now),Timestamp.from(now));return id;}private UUID enquiry(String name){UUID id=UUID.randomUUID();jdbc.update("INSERT INTO takura.enquiry(id,reference,state,team_code,full_name,email,preferred_contact,country_code,town_or_suburb,description,privacy_notice_version,privacy_acknowledged_at,marketing_opt_in,created_at) VALUES(?,?,'CLOSED','GENERAL',?,'person@example.invalid','EMAIL','ZA','Synthetic Area','Sensitive text must not be exported outside this request','demo-v1',?,false,?)",id,"PRIV-"+id.toString().substring(0,8),name,Timestamp.from(now),Timestamp.from(now));return id;}private StaffPrincipal requester(){return principal(requester,Set.of("privacy:manage"));}private StaffPrincipal approver(){return principal(approver,Set.of("privacy:approve"));}private StaffPrincipal exporter(){return principal(requester,Set.of("privacy:export"));}private StaffPrincipal holder(){return principal(requester,Set.of("privacy:hold"));}private StaffPrincipal deleter(){return principal(approver,Set.of("privacy:delete"));}private StaffPrincipal principal(UUID id,Set<String> operations){return new StaffPrincipal(id,"issuer",id.toString(),"client",now,Set.of(),Set.of(),operations);}}
